mapper.insert:
INSERT INTO conversation_session (
    id, user_id, aura_profile_id, channel, title, status, started_at, ended_at, summary, metadata
) VALUES (
    CAST(#{id} AS uuid), CAST(#{userId} AS uuid), CAST(#{auraProfileId,jdbcType=VARCHAR} AS uuid), #{channel}, #{title}, #{status}, #{startedAt}, #{endedAt}, #{summary}, COALESCE(CAST(#{metadata,jdbcType=VARCHAR} AS jsonb), '{}'::jsonb)
)

INSERT INTO emotion_snapshot (
    id, user_id, session_id, message_id, source, dominant_emotion, valence, arousal,
    intensity, emotion_scores, reason
) VALUES (
    CAST(#{id} AS uuid), CAST(#{userId} AS uuid), CAST(#{sessionId,jdbcType=VARCHAR} AS uuid), CAST(#{messageId,jdbcType=VARCHAR} AS uuid), #{source}, #{dominantEmotion}, #{valence}, #{arousal},
    #{intensity}, COALESCE(CAST(#{emotionScores,jdbcType=VARCHAR} AS jsonb), '{}'::jsonb), #{reason}
)
